use moloch_live_runtime::fundamental_policy::*;
use serde_json::json;use sha2::{Sha256,Digest};use std::collections::BTreeSet;
const NOW:u64=1_792_108_800_000;
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn fixture(n:u64)->(ReviewInput,Vec<Vec<u8>>){
 let node=json!({"market_id":"201","root":{"node_type":"contract","node_id":"301","contract_id":"301","contract_type":"Election Outcome","contract_details":{"contractType":"Election Outcome","resolutionType":"Party Winner","winnerName":"Republican Party","electionDate":"2026-11-03","officeLevel":"Federal","usState":"Synthetic","raceId":1,"stageId":2,"raceName":"Synthetic fixture","raceStage":"General"},"settled_with":null,"settlement_date":null,"title":"Synthetic Republican Party Winner"}});
 let bytes=vec![b"synthetic forecast, not live data".to_vec(),b"synthetic official ballot".to_vec(),serde_json::to_vec(&node).unwrap()];
 let sources=["forecast","official_ballot","official_contract_node"].iter().enumerate().map(|(i,k)|SourceRef{kind:k.to_string(),url:format!("https://fixture.invalid/{k}"),sha256:sha(&bytes[i]),published_at_ms:NOW-100,observed_at_ms:NOW-50,maximum_age_ms:120000}).collect();
 let r=ReviewInput{version:1,reviewer_id:"quantity-fixture".into(),assumption_label:"Synthetic structural quantity bound; no production approval".into(),run_id:"quantity-fixture".into(),bank_manifest_sha256:"a".repeat(64),tournament_id:"cup".into(),market_id:"201".into(),exchange_id:"101".into(),contract_id:"301".into(),side:"NO".into(),official_contract_root_sha256:official_contract_root_sha256(&node).unwrap(),existing_origin:None,same_side_top_ups:None,execution_policy:None,valuation_objective:None,ordinary_probability:"0.950000".into(),exceptional_probability_allowance:"0.010000".into(),minimum_exceptional_payout:"0.000000".into(),margin_per_share:"0.010000".into(),maximum_principal:"2000.000000".into(),maximum_quantity:n,reviewed_at_ms:NOW,expires_at_ms:NOW+120000,hold_until_ms:NOW+600000,payout_mapping_is_operator_assumption:true,revoke_existing:false,sources};(r,bytes)
}
fn verify(r:ReviewInput,bytes:&[Vec<u8>])->Result<Reviewed,Box<dyn std::error::Error>>{let trust:BTreeSet<_>=[review_sha256(&r)?].into();let hashes=bytes.iter().map(|b|sha(b)).collect::<Vec<_>>();let refs=bytes.iter().zip(&hashes).map(|(b,h)|SourceBytes{sha256:h,bytes:b}).collect::<Vec<_>>();Reviewed::verify(r,&refs,&trust,NOW)}
#[test]fn reviewed_total_quantity_boundary_is_distinct_from_principal_and_original_review_identity(){
 for n in [1,10_000,10_001,1_000_000]{let(r,b)=fixture(n);let hash=review_sha256(&r).unwrap();let raw=serde_json::to_vec(&r).unwrap();verify(r.clone(),&b).unwrap();assert_eq!(review_sha256(&serde_json::from_slice::<ReviewInput>(&raw).unwrap()).unwrap(),hash);assert_eq!(r.maximum_principal,"2000.000000");}
 for n in [0,1_000_001,u64::MAX]{let(r,b)=fixture(n);assert!(verify(r,&b).is_err(),"{n}");}
}
#[test]fn larger_quantity_review_cannot_relax_hash_allowlist_or_nonpositive_principal(){let(mut r,b)=fixture(1_000_000);r.maximum_principal="0.000000".into();assert!(verify(r,&b).is_err());let(r,b)=fixture(1_000_000);let refs=r.sources.iter().zip(&b).map(|(s,b)|SourceBytes{sha256:&s.sha256,bytes:b}).collect::<Vec<_>>();assert!(Reviewed::verify(r.clone(),&refs,&BTreeSet::new(),NOW).is_err());let mut wrong=r.clone();wrong.maximum_quantity=999999;let trust=[review_sha256(&wrong).unwrap()].into();assert!(Reviewed::verify(r.clone(),&refs,&trust,NOW).is_err());}
